package org.unforced.uni

// Hand-written (not generated by `tauri android init`), T-174: attachments the user saves or opens.
// The app's media cache is private storage, which no other app (and no file manager) can see:
// - saveToDownloads copies a cached file into the public Downloads collection through MediaStore
//   (Android 10+, no storage permission needed) and says what it is called there;
// - openFile hands a cached file to the app that views its type, as a FileProvider content:// URI
//   with a one-off read grant (ACTION_VIEW). A file:// path would crash on Android 7+.

import android.app.Activity
import android.content.ActivityNotFoundException
import android.content.ContentValues
import android.content.Intent
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import android.webkit.MimeTypeMap
import androidx.core.content.FileProvider
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin
import java.io.File

@InvokeArg
class SaveFileArgs {
  lateinit var path: String
  lateinit var name: String
  var mime: String? = null
}

@InvokeArg
class OpenFileArgs {
  lateinit var path: String
  var mime: String? = null
}

@TauriPlugin
class FilesPlugin(private val activity: Activity) : Plugin(activity) {
  /** The type other apps go by: from the extension first (it must agree with the name), else the imeta hint. */
  private fun mimeFor(name: String, hint: String?): String {
    val ext = name.substringAfterLast('.', "").lowercase()
    return MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext)
      ?: hint?.takeIf { it.matches(Regex("^[a-z0-9.+-]+/[a-z0-9.+-]+$")) }
      ?: "application/octet-stream"
  }

  /** `report.pdf` → `report (1).pdf`. */
  private fun numbered(name: String, n: Int): String {
    val dot = name.lastIndexOf('.')
    return if (dot > 0) "${name.substring(0, dot)} ($n)${name.substring(dot)}" else "$name ($n)"
  }

  /** Only files in the app's media cache, the one folder the FileProvider shares (res/xml/file_paths.xml). */
  private fun mediaFile(path: String): File? {
    val media = File(activity.cacheDir, "media").canonicalFile
    val file = File(path).canonicalFile
    return file.takeIf { it.parentFile == media && it.isFile }
  }

  @Command
  fun saveToDownloads(invoke: Invoke) {
    val args = try { invoke.parseArgs(SaveFileArgs::class.java) } catch (e: Exception) {
      invoke.reject("bad save request"); return
    }
    if (Build.VERSION.SDK_INT < 29) {
      invoke.reject("Saving to Downloads needs Android 10 or newer; use Open instead")
      return
    }
    val src = mediaFile(args.path)
    if (src == null) {
      invoke.reject("the downloaded file is missing; try again")
      return
    }
    // Up to 500 MB: not on the caller's thread.
    Thread {
      val resolver = activity.contentResolver
      val values = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, args.name)
        put(MediaStore.MediaColumns.MIME_TYPE, mimeFor(args.name, args.mime))
        put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
      }
      var uri: android.net.Uri? = null
      try {
        uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)
          ?: throw IllegalStateException("Downloads refused the file")
        resolver.openOutputStream(uri)?.use { out -> src.inputStream().use { it.copyTo(out, 1 shl 16) } }
          ?: throw IllegalStateException("could not write to Downloads")
        // Publishing moves the file to its name. MediaStore can refuse that name (UNIQUE files._data) when a row
        // for it outlived its file; then publish as "name (1).ext", … without copying again.
        for (n in 0..20) {
          val done = ContentValues().apply {
            put(MediaStore.MediaColumns.IS_PENDING, 0)
            if (n > 0) put(MediaStore.MediaColumns.DISPLAY_NAME, numbered(args.name, n))
          }
          try {
            resolver.update(uri, done, null, null)
            break
          } catch (e: Exception) {
            if (n == 20) throw e
          }
        }
        // MediaStore renames a duplicate ("report (1).pdf"): report the name it really has.
        var saved = args.name
        resolver.query(uri, arrayOf(MediaStore.MediaColumns.DISPLAY_NAME), null, null, null)?.use { c ->
          if (c.moveToFirst()) c.getString(0)?.let { saved = it }
        }
        val out = JSObject()
        out.put("name", saved)
        invoke.resolve(out)
      } catch (e: Exception) {
        uri?.let { runCatching { resolver.delete(it, null, null) } }
        invoke.reject("Couldn't save to Downloads: ${e.message ?: e.javaClass.simpleName}")
      }
    }.start()
  }

  @Command
  fun openFile(invoke: Invoke) {
    val args = try { invoke.parseArgs(OpenFileArgs::class.java) } catch (e: Exception) {
      invoke.reject("bad open request"); return
    }
    val file = mediaFile(args.path)
    if (file == null) {
      invoke.reject("the downloaded file is missing; try again")
      return
    }
    activity.runOnUiThread {
      try {
        val uri = FileProvider.getUriForFile(activity, "${activity.packageName}.fileprovider", file)
        val intent = Intent(Intent.ACTION_VIEW).apply {
          setDataAndType(uri, mimeFor(file.name, args.mime))
          addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        activity.startActivity(intent)
        invoke.resolve()
      } catch (e: ActivityNotFoundException) {
        invoke.reject("No app on this device opens this kind of file. Save it to Downloads instead")
      } catch (e: Exception) {
        invoke.reject("Couldn't open the file: ${e.message ?: e.javaClass.simpleName}")
      }
    }
  }
}
